#include <algorithm>
#include <iostream>
#include <limits>
#include <utility>
#include <vector>

using Interval = std::pair<int, int>;

int minRemovals(std::vector<Interval> intervals) {
    std::sort(intervals.begin(), intervals.end(), [](const Interval& a, const Interval& b) {
        return a.second < b.second;
    });
    int removed = 0;
    int lastEnd = std::numeric_limits<int>::min();
    for (const Interval& interval : intervals) {
        if (interval.first < lastEnd) {
            removed++;
        } else {
            lastEnd = interval.second;
        }
    }
    return removed;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<Interval> intervals(n);
    for (int i = 0; i < n; i++) {
        std::cin >> intervals[i].first >> intervals[i].second;
    }
    std::cout << minRemovals(intervals) << "\n";
    return 0;
}

