import java.util.Scanner;

public class Main {
    static int minRemovals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
        int removed = 0;
        int lastEnd = Integer.MIN_VALUE;
        for (int[] interval : intervals) {
            if (interval[0] < lastEnd) {
                removed++;
            } else {
                lastEnd = interval[1];
            }
        }
        return removed;
    }

